   419	function readWorkerProposalInvocationPrivateKey(
   420	  env: NodeJS.ProcessEnv,
   421	): string | undefined {
   422	  const rawFd = env.LATTICE_MANAGED_HOST_WORKER_CAPABILITY_FD?.trim();
   423	  if (!rawFd) return undefined;
   424	  const fd = Number(rawFd);
   425	  if (!Number.isInteger(fd) || fd < 3 || fd > 255) {
   426	    throw new Error('managed host run worker: proposal capability fd must be between 3 and 255');
   427	  }
   428	  const stat = fstatSync(fd);
   429	  if (stat.isFile()) {
   430	    throw new Error('managed host run worker: proposal capability must arrive over a non-file descriptor');
   431	  }
   432	  const key = readFileSync(fd, 'utf8').trim();
   433	  if (!/^[A-Za-z0-9+/]{43}=$/.test(key)) {
   434	    throw new Error('managed host run worker: proposal capability descriptor is malformed');
   435	  }
   436	  return key;
   437	}
