  1958	 * Explicit bounded GC used by doctor --repair. Active/corrupt runs and any
  1959	 * directory still carrying one-shot secrets are retained fail-closed.
  1960	 */
  1961	export function pruneExpiredManagedHostRuns(
  1962	  root: string,
  1963	  options: { now?: number; retentionMs?: number } = {},
  1964	): ManagedHostRunGcResult {
  1965	  const scan = scanManagedHostRunRuntime(root, options);
  1966	  const result: ManagedHostRunGcResult = { removed: [], archivedReceipts: [], retained: [], failed: [] };
  1967	  for (const run of scan.runs) {
  1968	    if (run.state === 'corrupt') {
  1969	      result.retained.push({ runId: run.runId, reason: 'corrupt_runtime_retained_for_manual_review' });
  1970	      continue;
  1971	    }
  1972	    if (!['completed', 'failed', 'cancelled', 'timed_out'].includes(run.state)) {
  1973	      result.retained.push({ runId: run.runId, reason: 'active_run_protected' });
  1974	      continue;
  1975	    }
  1976	    if (run.hasUnconsumedOneShotInputs) {
  1977	      result.retained.push({ runId: run.runId, reason: 'one_shot_inputs_present_retained' });
  1978	      continue;
  1979	    }
  1980	    if (!run.retentionExpired) {
  1981	      result.retained.push({ runId: run.runId, reason: 'within_terminal_retention_window' });
  1982	      continue;
  1983	    }
  1984	    try {
  1985	      const paths = pathsFor(root, run.runId);
  1986	      const archivePath = managedHostRunReceiptArchivePath(root, run.runId);
  1987	      mkdirSync(managedHostRunReceiptsRoot(root), { recursive: true, mode: 0o700 });
  1988	      const archive: ManagedHostRunReceiptArchive = {
  1989	        schemaVersion: 'lattice.managed_host_run_receipt_archive.v1',
  1990	        runId: run.runId,
  1991	        archivedAt: run.terminalAt ?? new Date(options.now ?? Date.now()).toISOString(),
  1992	        receipt: managedHostRunReceipt(root, run.runId),
  1993	        evidenceBindingDigest: digestFile(paths.evidenceBinding),
  1994	      };
  1995	      if (!writeExclusive(archivePath, archive)) {
  1996	        const existing = readJson<ManagedHostRunReceiptArchive>(archivePath);
  1997	        if (existing.receipt.receiptId !== archive.receipt.receiptId) {
  1998	          throw new Error('existing archived receipt does not match terminal receipt');
  1999	        }
  2000	      }
  2001	      removeManagedHostRunRuntime(root, run.runId);
  2002	      result.removed.push(run.runId);
  2003	      result.archivedReceipts.push(run.runId);
  2004	    } catch (error) {
  2005	      result.failed.push({ runId: run.runId, error: error instanceof Error ? error.message : String(error) });
  2006	    }
  2007	  }
