   241	export function classifyProviderRegistryLock(snapshot: ExistingMkdirLockSnapshot): ExistingMkdirLockState {
   242	  const holder = snapshot.holder;
   243	  if (!holder || holder.hostname !== hostname()) return 'unknown';
   244	  if (!Number.isInteger(holder.pid) || holder.pid <= 0) return 'unknown';
   245	  try {
   246	    process.kill(holder.pid, 0);
   247	  } catch (error) {
   248	    const code = (error as NodeJS.ErrnoException).code;
   249	    if (code === 'ESRCH') return 'stale';
   250	    if (code !== 'EPERM') return 'unknown';
   251	  }
   252	  if (
   253	    holder.pid === process.pid
   254	    && !sameProcessStart(holder.processStartTimeMs, currentProcessStartTimeMs())
   255	  ) return 'stale';
   256	  return 'active';
   257	}
