   265	    label: 'provider-process-registry',
   266	    deadlineMs: timing.deadlineMs ?? 30_000,
   267	    staleMs: timing.staleMs ?? 10_000,
   268	    pollMs: timing.pollMs ?? 10,
   269	    requireHolderToken: true,
   270	    classifyExistingLock: classifyProviderRegistryLock,
   271	    holderInfo: {
   272	      pid: process.pid,
   273	      hostname: hostname(),
   274	      command: 'provider-process-registry mutation',
   275	      acquiredAt: new Date().toISOString(),
   276	      lockId: randomUUID(),
   277	      processStartTimeMs: currentProcessStartTimeMs(),
   278	    },
   279	  });
   280	  try {
   281	    return fn();
   282	  } finally {
   283	    lock.release();
   284	  }
   285	}
