   301	  meta: ProviderProcessSlotMeta,
   302	  lockTiming: ProviderRegistryLockTiming = {},
   303	): AcquiredProviderProcessSlot | null {
   304	  mkdirSync(dir, { recursive: true });
   305	  const boundedCap = Number.isFinite(cap) && Number.isInteger(cap) && cap > 0
   306	    ? cap
   307	    : PROVIDER_PROCESS_MAX_CONCURRENT_DEFAULT;
   308	  return withProviderRegistryLock(dir, () => {
   309	    const live = scanLiveProviderProcessSlotsUnlocked(dir, now, staleMs);
   310	    if (live.length >= boundedCap) return null;
   311	    const token = randomUUID();
   312	    const record: ProviderProcessSlotFileMeta = { ...meta, token };
   313	    for (let index = 0; index < boundedCap; index += 1) {
   314	      const file = join(dir, `slot-${index}.json`);
   315	      if (writeProviderProcessSlotExclusive(file, record)) return { file, token };
   316	      const judged = readSlotOccupant(file);
   317	      if (!slotReclaimable(judged, file, now, staleMs)) continue;
   318	      if (judged.state !== 'missing') {
   319	        if (!sameSlotOccupant(readSlotOccupant(file), judged)) continue;
   320	        try { unlinkSync(file); } catch { /* exclusive recreate decides the winner */ }
   321	      }
   322	      if (writeProviderProcessSlotExclusive(file, record)) return { file, token };
   323	    }
   324	    return null;
   325	  }, lockTiming);
   326	}
