   335	  try {
   336	    withProviderRegistryLock(dir, () => {
   337	      try {
   338	        const occupant = readSlotOccupant(file);
   339	        if (occupant.state !== 'valid' || occupant.token !== token) return;
   340	        unlinkSync(file);
   341	      } catch {
   342	        // Best effort: pid-death or corrupt-meta staleness will reclaim a leak.
   343	      }
   344	    }, lockTiming);
   345	  } catch {
   346	    // Best effort: a later acquire reclaims this slot after the holder exits.
   347	  }
   348	}
