   350	export function transferProviderProcessSlotToProvider(
   351	  file: string | null,
   352	  token: string | null,
   353	  identity: {
   354	    pid: number;
   355	    pgid: number | null;
   356	    spawnedAt: string;
   357	    startFingerprint: string | null;
   358	    processGroupIsolated: boolean;
   359	  },
   360	  lockTiming: ProviderRegistryLockTiming = {},
   361	): boolean {
   362	  if (!file || !token) return false;
   363	  if (
   364	    !Number.isInteger(identity.pid) || identity.pid <= 0
   365	    || !identity.processGroupIsolated
   366	    || !Number.isInteger(identity.pgid) || (identity.pgid ?? 0) <= 0
   367	  ) return false;
   368	  const dir = dirname(file);
   369	  return withProviderRegistryLock(dir, () => {
   370	    const occupant = readSlotOccupant(file);
   371	    if (occupant.state !== 'valid' || occupant.token !== token) return false;
   372	    const next: ProviderProcessSlotFileMeta = {
   373	      ...(occupant.meta as unknown as ProviderProcessSlotFileMeta),
   374	      pid: identity.pid,
   375	      providerPid: identity.pid,
   376	      providerPgid: identity.pgid!,
   377	      providerSpawnedAt: identity.spawnedAt,
   378	      providerStartFingerprint: identity.startFingerprint ?? undefined,
   379	      providerProcessGroupIsolated: true,
   380	      token,
