   385	      // Registry lock + exact token check makes this replacement ownership-safe.
   386	      renameSync(temporary, file);
   387	    } finally {
   388	      try { unlinkSync(temporary); } catch { /* rename already consumed it */ }
   389	    }
   390	    return true;
   391	  }, lockTiming);
   392	}
