   404	  const worktree = join(parent, 'worktree');
   405	  try {
   406	    execFileSync('git', ['worktree', 'add', '--detach', worktree, headHash], {
   407	      cwd: gitCwd,
   408	      encoding: 'utf-8',
   409	      stdio: ['ignore', 'pipe', 'pipe'],
   410	      maxBuffer: GIT_TREE_OUTPUT_MAX_BUFFER,
   411	    });
   412	  } catch (err) {
   413	    rmSync(parent, { recursive: true, force: true });
   414	    throw new Error(
   415	      `cross_host_review: cannot create a clean HEAD review snapshot for codex at ${headHash} (${err instanceof Error ? err.message : String(err)}); `
   416	      + 'refusing to review the mutable live worktree (fail-closed).',
   417	    );
   418	  }
   419	
   420	  const cleanup = (): void => cleanupHeadReviewWorktree(gitCwd, worktree);
