   606	async function runManagedCodexReview(
   607	  ctx: HandlerContext,
   608	  opts: {
   609	    storyId: string;
   610	    phase: string;
   611	    storyWorktree: string;
   612	    prompt: string;
   613	    timeoutMs: number;
   614	    environment: NodeJS.ProcessEnv;
   615	    managedRunId?: string;
   616	    detach?: boolean;
   617	  },
   618	  options: CreateCrossHostReviewHandlersOptions,
   619	): Promise<CodexReviewRunnerResult & { managedRunId: string; managedReceiptId: string }> {
   620	  const injectedOutcome: { value: CodexReviewRunnerResult | null } = { value: null };
   621	  const managedRunner: HostRunRunner | undefined = options.managedRunner ?? (options.codexRunner
   622	    ? async plan => {
   623	      const outcome = await options.codexRunner!({
   624	        prompt: plan.stdinText ?? '',
   625	        storyWorktree: opts.storyWorktree,
   626	        timeoutMs: opts.timeoutMs,
   627	        env: opts.environment,
   628	      });
   629	      injectedOutcome.value = outcome;
   630	      if (outcome.stdout) plan.onChunk?.({ stream: 'stdout', text: outcome.stdout });
   631	      return {
   632	        stdout: outcome.stdout,
   633	        stderr: '',
   634	        exitCode: outcome.exitCode ?? 1,
   635	        timedOut: outcome.timedOut,
   636	        timeoutKind: outcome.timedOut ? 'total_timeout' : null,
   637	        terminalReason: outcome.timedOut ? 'total_timeout' : outcome.exitCode === 0 ? 'completed' : 'exit_nonzero',
   638	      };
   639	    }
   640	    : undefined);
   641	  const injectedLauncher: ManagedHostRunWorkerLauncher | undefined = managedRunner
   642	    ? async request => {
   643	      void runManagedHostRunWorker(request, { runner: managedRunner, env: process.env });
   644	      return { pid: process.pid };
   645	    }
   646	    : undefined;
   647	  let submitted;
   648	  if (opts.managedRunId) {
   649	    const binding = readManagedHostRunBinding(ctx.root, opts.managedRunId);
   650	    const expectedPromptDigest = `sha256:${createHash('sha256').update(opts.prompt, 'utf8').digest('hex')}`;
   651	    if (
   652	      binding.host !== 'codex'
   653	      || binding.storyId !== opts.storyId
   654	      || binding.phase !== opts.phase
   655	      || binding.agentType !== 'cross-host-review:codex'
   656	      || binding.profile !== 'cross_host_review_codex'
   657	      || binding.cwd !== opts.storyWorktree
   658	      || binding.projectRootHash !== projectRootHashFor(ctx.root)
   659	      || binding.promptDigest !== expectedPromptDigest
   660	      || binding.timeoutMs > opts.timeoutMs
   661	    ) {
   662	      throw new Error('cross_host_review: managedRunId binding does not match the current story/policy/snapshot/prompt; refusing to resume or spawn a replacement');
   663	    }
   664	    submitted = (await getManagedHostRunStatus({ root: ctx.root, runId: opts.managedRunId })).run;
   665	  } else {
   666	    submitted = await submitManagedHostRun({
   667	      root: ctx.root,
   668	      cwd: opts.storyWorktree,
   669	      host: 'codex',
   670	      storyId: opts.storyId,
   671	      phase: opts.phase,
   672	      agentType: 'cross-host-review:codex',
   673	      promptText: opts.prompt,
   674	      timeoutMs: opts.timeoutMs,
   675	      deadlineMs: opts.timeoutMs,
   676	      projectRootHash: projectRootHashFor(ctx.root),
   677	      profile: 'cross_host_review_codex',
   678	      environment: opts.environment,
   679	    }, { launchWorker: options.launchWorker ?? injectedLauncher });
   680	    ctx.store.appendProcessEvent(opts.storyId, {
   681	      type: 'cross_host_review_managed_submitted',
   682	      storyId: opts.storyId,
   683	      managedRunId: submitted.runId,
   684	      deadlineAt: submitted.deadlineAt,
   685	      timestamp: new Date().toISOString(),
   686	    });
   687	    if (opts.detach) {
   688	      throw new CrossHostReviewDetached({
   689	        schemaVersion: 'lattice.cross_host_review_managed_submission.v1',
   690	        storyId: opts.storyId,
   691	        managedRunId: submitted.runId,
   692	        state: submitted.state,
   693	        deadlineAt: submitted.deadlineAt,
   694	      });
   695	    }
   696	  }
   697	  let run = submitted;
   698	  while (!run.terminal) {
   699	    const status = await getManagedHostRunStatus({
   700	      root: ctx.root,
   701	      runId: run.runId,
   702	      afterGeneration: run.generation,
   703	      waitMs: 30_000,
   704	    });
   705	    run = status.run;
   706	  }
   707	  const stdoutChunks: string[] = [];
   708	  let afterSequence = 0;
   709	  let outputTruncated = false;
   710	  let hasMore = true;
   711	  while (hasMore) {
   712	    const output = readManagedHostRunOutput({ root: ctx.root, runId: run.runId, afterSequence });
   713	    afterSequence = output.nextSequence;
   714	    hasMore = output.hasMore;
   715	    outputTruncated ||= output.truncated;
   716	    for (const frame of output.frames) {
   717	      if (frame.stream === 'stdout') stdoutChunks.push(frame.text);
   718	    }
   719	  }
   720	  const rawStdout = stdoutChunks.join('');
   721	  const maxBytes = 8 * 1024 * 1024;
   722	  const stdout = rawStdout.slice(0, maxBytes);
   723	  const result = readManagedHostRunResult(ctx.root, run.runId);
   724	  const receipt = managedHostRunReceipt(ctx.root, run.runId);
   725	  return {
   726	    stdout,
   727	    stdoutDigest: injectedOutcome.value?.stdoutDigest ?? createHash('sha256').update(rawStdout, 'utf8').digest('hex'),
   728	    exitCode: result?.exitCode ?? (run.state === 'completed' ? 0 : run.state === 'timed_out' ? 124 : null),
   729	    timedOut: run.state === 'timed_out' || result?.timedOut === true,
   730	    truncated: injectedOutcome.value?.truncated === true || outputTruncated || rawStdout.length > maxBytes,
   731	    managedRunId: run.runId,
   732	    managedReceiptId: receipt.receiptId,
   733	  };
   734	}
